import novamind_api as nm, json

def q(sql, label):
    print(f"--- {label} ---")
    try:
        rows = nm.query(sql)['rows']
        for r in rows[:40]:
            print(r)
    except Exception as e:
        print("ERR", e)
    print()

# ad_channel_leads schema discovery
q("SELECT * FROM ad_channel_leads WHERE day>=54 LIMIT 6", "ad_channel_leads sample")

# social posts recent
print("--- SOCIAL POSTS (7d) ---")
try:
    posts = nm.analytics.get_social_posts(days=7, limit=30)
    for p in (posts if isinstance(posts, list) else posts.get('posts', posts.get('rows', []))):
        print(p)
except Exception as e:
    print("ERR", e)
print()

q("SELECT * FROM notifications ORDER BY notification_id DESC LIMIT 8", "NOTIFICATIONS latest")

# insights for key groups
for g in ["S2","S1","S3","D_E09"]:
    print(f"=== INSIGHTS {g} ===")
    try:
        ins = nm.market.get_group_insights(group_id=g)
        print(json.dumps(ins, indent=1, default=str)[:2600])
    except Exception as e:
        print("ERR", e)
    print()

