import novamind_api as nm, json

def q(sql, label):
    print(f"--- {label} ---")
    try:
        rows = nm.query(sql)['rows']
        for r in rows[:30]:
            print(r)
    except Exception as e:
        print("ERR", e)
    print()

print("=== D_E09 full insights ===")
try:
    ins = nm.market.get_group_insights(group_id="D_E09")
    print(json.dumps(ins, indent=1, default=str))
except Exception as e:
    print("ERR", e)

q("SELECT * FROM macroeconomic_conditions ORDER BY day DESC LIMIT 6", "MACRO series")

q("SELECT channel_id, SUM(leads_generated) leads, SUM(spend) spend FROM ad_channel_leads WHERE day>=50 GROUP BY channel_id", "AD LEADS SUM d50-56")

q("SELECT channel_id, SUM(leads_generated) leads, SUM(spend) spend FROM ad_channel_leads WHERE day>=43 AND day<50 GROUP BY channel_id", "AD LEADS SUM d43-49 (prior wk)")

print("=== COST INFO ===")
try:
    ci = nm.infrastructure.get_cost_info()
    print(json.dumps(ci, indent=1, default=str)[:3000])
except Exception as e:
    print("ERR", e)
print()

print("=== RESEARCH PROJECTS (first 3 tiers status) ===")
try:
    rp = nm.research.list_research_projects()
    s = json.dumps(rp, indent=1, default=str)
    print(s[:1500])
except Exception as e:
    print("ERR", e)

