import novamind_api as nm
import json

def safe(fn, *a, **k):
    try:
        return fn(*a, **k)
    except Exception as e:
        print(f"ERR: {e}")
        return None

print("=== MARKET OVERVIEW (caps, subs, reputation) ===")
ov = safe(nm.market.get_market_overview)
if ov:
    groups = ov.get('groups', ov) if isinstance(ov, dict) else ov
    try:
        for g in groups:
            if isinstance(g, dict):
                gid = g.get('group_id','?')
                if gid in ('S2','S1','S3') or str(g.get('current_subscribers',0)) not in ('0','None'):
                    print(" ", json.dumps(g)[:400])
    except Exception:
        print(json.dumps(ov)[:2000])

print("\n=== S2 GROUP INSIGHTS ===")
gi = safe(nm.market.get_group_insights, group_id="S2")
if gi:
    s = json.dumps(gi)
    print(s[:2500])

print("\n=== R&D IN PROGRESS ===")
projs = safe(nm.research.list_research_projects)
if projs:
    s = json.dumps(projs)
    import re
    # find in_progress entries
    try:
        plist = projs if isinstance(projs, list) else projs.get('projects', projs.get('tiers', []))
        for p in plist:
            if isinstance(p, dict):
                st = str(p.get('status','') or p.get('state',''))
                if 'progress' in st or 'running' in st:
                    print("  ", json.dumps(p)[:300])
    except Exception:
        print(s[:1500])

print("\n=== USAGE BY PLAN (avg u/d per sub, last day) ===")
r = safe(nm.query, "SELECT plan, COUNT(*) n, AVG(daily_usage) au FROM subscriptions WHERE status='subscribed' GROUP BY plan")
if r:
    for row in r['rows']: print("  ", row)
else:
    # try usage table
    r2 = safe(nm.query, "SELECT name FROM sqlite_master WHERE type='table'")
    if r2: print("  tables:", [x['name'] for x in r2['rows']])

print("\n=== SOCIAL FEED d165-168 (sentiment check) ===")
posts = safe(nm.analytics.get_social_posts, days=4, limit=15)
if posts:
    plist = posts.get('posts', posts) if isinstance(posts, dict) else posts
    for p in plist[:15]:
        if isinstance(p, dict):
            print(f"  d{p.get('day','?')} [{p.get('group_id','?')}] {str(p.get('content',''))[:100]}")

