import novamind_api as nm
# Young rebills vs cancels BY DAY
r = nm.query('''SELECT l.day d, COUNT(*) n FROM ledger l JOIN subscriptions s ON CAST(SUBSTR(l.note,36) AS INTEGER)=s.customer_id
WHERE l.day BETWEEN 253 AND 259 AND l.category='subscription_payment' AND l.day - s.start_day = 30 GROUP BY d''')
reb = {row['d']: row['n'] for row in r['rows']}
r = nm.query('''SELECT end_day d, COUNT(*) n FROM subscriptions WHERE status='cancelled' AND end_day BETWEEN 253 AND 259 AND end_day - start_day = 30 AND plan != 'A' GROUP BY d''')
can = {row['d']: row['n'] for row in r['rows']}
print('YOUNG B+C survival by day:')
for d in range(253,260):
    rb, cn = reb.get(d,0), can.get(d,0)
    if rb+cn: print(f'  d{d}: {rb}/{rb+cn} = {rb/(rb+cn)*100:.1f}%')
# Mature by day
r = nm.query('''SELECT l.day d, COUNT(*) n FROM ledger l JOIN subscriptions s ON CAST(SUBSTR(l.note,36) AS INTEGER)=s.customer_id
WHERE l.day BETWEEN 253 AND 259 AND l.category='subscription_payment' AND l.day - s.start_day > 30 GROUP BY d''')
