import novamind_api as nm

def q(sql):
    return nm.query(sql)['rows']

print("--- config_overrides since d335 ---")
for r in q("SELECT day, tool_name, settings_json FROM config_overrides WHERE day>=335 ORDER BY day, id"):
    print(r['day'], r['tool_name'], r['settings_json'][:220])

print("--- notifications since d340 ---")
for r in q("SELECT day, type, message FROM notifications WHERE day>=340 ORDER BY day"):
    print(r['day'], r['type'], (r['message'] or '')[:180])

print("--- raw posts d343-350 ---")
for r in q("SELECT day, content FROM social_media_posts WHERE day BETWEEN 343 AND 350 ORDER BY day, post_id"):
    print(r['day'], '|', (r['content'] or '')[:240])
    print()

print("--- config_history d340-350 (dev/ops/prices) ---")
for r in q("SELECT day, price_B, price_C, tier_B, tier_C, spend_operations, spend_development, quota_B, quota_C FROM config_history WHERE day>=340 ORDER BY day"):
    print(r)

import novamind_api as nm
import re

def q(sql):
    return nm.query(sql)['rows']

# Event magnitudes by day d230-350 from posts
rows = q("SELECT day, content FROM social_media_posts WHERE day BETWEEN 230 AND 350 ORDER BY day, post_id LIMIT 5000")
agg = {}
for r in rows:
    c = (r['content'] or '')
    m = re.search(r'(\d\.\d{3,4}) quality (boost|bump)', c)
    if m:
        agg.setdefault((r['day'], m.group(1)), True)
ev = {}
for (d, mag) in agg:
    ev[d] = ev.get(d, 0.0) + float(mag)

# Cancels by day
cx = {}
for r in q("SELECT end_day d, COUNT(*) n FROM subscriptions WHERE status='cancelled' AND end_day BETWEEN 230 AND 350 GROUP BY end_day"):
    cx[r['d']] = r['n']

print("day | event_mag | cancels")
for d in range(230, 351):
    e = ev.get(d, 0.0)
    c = cx.get(d, 0)
    bar = '#' * min(60, int(c/20))
    estr = f"{e:.3f}" if e else "     "
    print(f"{d:3d} | {estr} | {c:5d} {bar}")

